function waitForElement(cls, callback) {
  var tickTick = setInterval(function () {
    if (document.querySelectorAll(cls).length > 2) {
      clearInterval(tickTick);
      callback();
    }
  }, 100);
}

waitForElement(".accordion-btn", function () {
  var accordionBtn = document.getElementsByClassName("accordion-btn");
  var i;

for (i = 0; i < accordionBtn.length; i++) {
  accordionBtn[i].addEventListener("click", function () {
    for (var j = 0; j < accordionBtn.length; j++) {
      if (accordionBtn[j] !== this) {
        accordionBtn[j].classList.remove("active");
        accordionBtn[j].nextElementSibling.style.maxHeight = null;
      }
    }

    this.classList.toggle("active");
    var panel = this.nextElementSibling;
    if (panel.style.maxHeight) {
      panel.style.maxHeight = null;
    } else {
      panel.style.maxHeight = panel.scrollHeight + "px";
    }
  });
}
});
